"""Build truthful product/help pages using only the standard library."""
from pathlib import Path
import html
ROOT=Path(__file__).resolve().parents[1]
BASE='https://gonisulaimann.github.io/'
REPO='https://github.com/gonisulaimann/Prepare'
PAGES={
'download':('Download','Choose a tested build, not a platform promise.', '''<h2>Intel Mac preview</h2><p>Native image-to-PDF app, version 0.5.0, newly qualified on an Intel runner and offered alongside this beta. macOS 14+; ad-hoc signed, not notarized. It does not include the PDF Workbench features. Existing Apple Silicon stable downloads are unchanged.</p><p><a class="button" href="https://github.com/gonisulaimann/Prepare/releases/download/v0.7.0-beta.1/Prepare-0.5.0-x86_64.zip">Download Intel Mac preview</a> <a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.7.0-beta.1/Prepare-0.5.0-x86_64.zip.sha256">SHA-256</a></p><h2 id="pdf-workbench">PDF Workbench</h2><p class="release-status">Beta · 0.7.0-beta.1 · Windows / Linux / macOS desktop browsers</p><p>For existing PDFs: merge, extract, reorder, duplicate and rotate real pages while retaining text/vector content. Extract the entire ZIP and open index.html. No installation or network connection needed. Ordinary unencrypted PDFs only; forms, annotations and signatures are not supported. Not a PDF compressor or sanitizer.</p><p><a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.7.0-beta.1/Prepare-0.7.0-beta.1-pdf-workbench.zip">Download PDF Workbench ZIP</a> · <a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.7.0-beta.1/Prepare-0.7.0-beta.1-pdf-workbench.zip.sha256">SHA-256</a></p><h2>macOS</h2><p class="release-status">Stable · 0.5.0 · Apple Silicon</p><p>Apple Silicon, macOS 14+. Ad-hoc signed, not notarized. Intel users can use Portable; no tested Intel native binary is offered.</p><p><a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.5.0/Prepare-0.5.0-arm64.zip">Download Mac ZIP</a> · <a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.5.0/Prepare-0.5.0-arm64.zip.sha256">SHA-256</a></p><h2>Desktop browser bundle</h2><p class="release-status">Stable · Portable 0.5.0 · Windows / Linux / macOS</p><p>Extract the folder and open index.html in current Chrome, Edge or Firefox. No installer or bundled runtime. Not an EXE, MSIX, AppImage or Flatpak.</p><p><a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.5.0/Prepare-0.5.0-portable.zip">Download Portable ZIP</a> · <a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.5.0/Prepare-0.5.0-portable.zip.sha256">SHA-256</a></p><h2>Android</h2><p class="release-status">Developer experimental · 0.5.0 · Unsigned</p><p>Android 9+. Unsigned APK: your own signing is required. Not a tap-to-install consumer release. Tested on API levels 28 and 36 emulators, not comprehensively qualified on physical devices.</p><p><a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.5.0-android-experimental.1/Prepare-0.5.0-android-experimental-UNSIGNED.apk">Unsigned developer APK</a> · <a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.5.0-android-experimental.1/Prepare-0.5.0-android-experimental-UNSIGNED.apk.sha256">SHA-256</a></p><h2>iOS / iPadOS</h2><p class="release-status">Not supported</p><p>No supported build or App Store listing yet. Do not rely on the desktop-browser bundle for untested mobile workflows.</p><h2 id="readiness-beta">Readiness workbench</h2><p class="release-status">Beta · 0.6.0-beta.1 · Desktop browsers</p><p>Shared readiness checks, reversible page actions and offline JSON profiles. Structure remains UNKNOWN: this is not PDF certification. Extract the complete bundle; no Node or server needed.</p><p><a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.6.0-beta.1/Prepare-0.6.0-beta.1-portable.zip">Download readiness beta ZIP · 24.5 KB</a> · <a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.6.0-beta.1/Prepare-0.6.0-beta.1-portable.zip.sha256">SHA-256</a></p><h2>Source CLI</h2><p>Beta · Node.js 22+ required separately. Header inspection, hashing, profile validation and model-only workflow dry runs; not file conversion.</p><p><a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.6.0-beta.1/document-engine-source.zip">Download source CLI ZIP · 30.3 KB</a> · <a href="https://github.com/gonisulaimann/Prepare/releases/download/v0.6.0-beta.1/document-engine-source.zip.sha256">SHA-256</a> · <a href="/documentation/CLI.html">CLI instructions</a></p><h2>Install and verify</h2><p><a href="/getting-started/">Installation guide</a> · <a href="/releases/">Release notes</a></p>'''),
'features':('Features','A document is ready only when the evidence says so.', '''<h2>New in the 0.7 PDF beta</h2><p>Real PDF merge, extraction, reordered and duplicated pages, clockwise rotation, reversible browser history and an exclusive-output CLI. The same locally bundled adapter runs in browser workers and Node. Outputs are parsed again and page geometry checked. Full PDF conformance and visual fidelity remain unverified.</p><h2>Readiness foundation</h2><p>Shared tri-state readiness, offline JSON requirement profiles and reversible page operations with undo/redo. A separate source CLI inspects headers and hashes files; its workflows edit a model, not a PDF.</p><p><a href="/download/#readiness-beta">Try the beta</a> · <a href="/documentation/ENGINE-ARCHITECTURE.html">Engine architecture</a></p><h2>Working in stable converters</h2><p>Convert JPEG/PNG images into ordered size-constrained raster PDFs. Reorder, rotate, duplicate and remove pages. Set compression, paper and margins. Preserve original files.</p><h2>Platform-specific strengths</h2><p>Mac: HEIC, PDFKit review and true grayscale PDF streams. Portable: spread splitting, arbitrary DPI ceiling and optional near-white cleanup. Android experimental: native image selection, layout, serial decode and verified save-copy bytes.</p><h2>Not claimed</h2><p>Stable converters accept images. The separate PDF beta handles ordinary pages, but does not edit text, run OCR, fill forms, encrypt output or certify PDF/A. Readability requires human review; a byte limit alone is not proof of submission acceptance.</p>'''),
'platforms':('Platforms','One product direction. Explicit support boundaries.', '''<h2>Available</h2><p>Native macOS on Apple Silicon; Portable in existing Windows/Linux/macOS desktop browsers; unsigned Android engineering artifact.</p><h2>PDF beta</h2><p>Existing Windows/Linux/macOS desktop browsers and Node 22+ share the same PDF page adapter. No native Windows/Linux app or mobile PDF support is implied.</p><h2>Architecture</h2><p>Platform image codecs and save dialogs remain adapters. Shared readiness rules and declarative model workflows run independently of UI in the 0.6 beta. Portable and the source CLI consume the same module. Shipping 0.5 converters retain their existing implementations; full unification is not claimed.</p><h2>Not yet distributed</h2><p>Windows x64/ARM64 native hosts, Linux packages, native Intel Mac, iOS/iPadOS and additional platforms need their own build, install and device qualification. No compatibility follows merely from source portability.</p><p><a href="/download/">Available downloads</a></p>'''),
'getting-started':('Getting started','Prepare a separate copy. Review before you submit.', '''<h2>Starting with an existing PDF?</h2><p>Use the separate <a href="/download/#pdf-workbench">PDF Workbench beta</a>. Add ordinary PDFs, arrange the numbered source pages, set the size ceiling and create a copy. To extract a subset, remove unwanted pages; to merge, add more source files. Reopen the saved file in a trusted PDF reader and review every page. Import resets history; closing the tab discards it. For image scans, use the converter instructions below.</p><h2>1. Install or open</h2><p>Mac: extract the ZIP and open Prepare.app. It is not notarized; use your normal organization-approved app policy. Never disable Gatekeeper globally. Portable: extract all files and open index.html, not a page still inside the ZIP. Android: follow the developer signing instructions in its source directory.</p><h2>2. Set the requirement</h2><p>Read the destination’s current rules. Choose a decimal MB limit, page size, margins and compression profile. Generic presets are examples, not verified institution requirements.</p><h2>3. Add and arrange</h2><p>Use local synthetic or non-sensitive images while learning. Add up to 20 supported images. Sort, move, rotate or remove pages using buttons; drag is never required.</p><h2>4. Prepare and check</h2><p>Review every output page, including faint stamps, signatures and small text. If the quality floor cannot meet the cap, reduce pages or raise the limit. A failed operation must not offer a successful result.</p><h2>5. Save a new file</h2><p>Use a local, unsynced destination and a new name. Mac enforces exclusive export; browser downloads and Android providers have their own overwrite behavior. Check the final file in an independent reader.</p>'''),
'privacy':('Privacy policy','Document processing stays on your device.', '''<h2>Applications</h2><p>I’m Goni Sulaiman, the independent maintainer. I do not operate a document upload service, account system or analytics endpoint for these apps. Released converters process documents locally. Portable blocks connections with Content Security Policy; Android requests no network permission. The Mac release is not sandboxed, so this is not a claim of OS-enforced network isolation.</p><h2>Local data</h2><p>Selected originals remain unchanged by conversion. Workspaces, generated versions, temporary data, browser downloads, OS swap and backups can contain sensitive information. Closing or deleting a file is not guaranteed forensic erasure. Use local storage and device encryption appropriate to your needs.</p><h2>Third parties</h2><p>This website, source and downloads are hosted by GitHub, which receives normal web requests and may log IP addresses. Opening documentation or update links is networking. System file pickers may expose cloud providers; selecting them can involve their services even though the engine itself never uploads documents. Browser extensions have separate access policies.</p><h2>Support</h2><p>Public issues are public. Do not attach identity documents, secrets or real confidential samples. For vulnerabilities use the private reporting link on the Security page. There is no automatic diagnostic upload.</p><p><a href="/contact/">Contact routes</a> · <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub privacy statement</a></p>'''),
 'terms':('Terms of use','License terms, limitations and your responsibility.', '''<h2>Software license</h2><p>The Hippocratic License 3.0 core governs use, modification and distribution. Its actual text controls; this page does not replace it or remove its ethical-use conditions. This is ethical-source software, not OSI-approved open source.</p><h2>No acceptance guarantee</h2><p>Profiles and measurements do not guarantee that an institution, employer, government or recipient will accept your document. Confirm their current requirements and review the final copy. No legal, immigration or archival certification is provided.</p><h2>Originals and output</h2><p>Keep independent backups. Lossy conversion can remove detail and metadata. Use only documents you are authorized to process. Platform permissions and destination providers remain your responsibility.</p><h2>Warranty and liability</h2><p>The software is provided under the warranty and liability terms in the license. No paid service-level agreement or support response time is promised.</p><p><a href="/licensing/">Read the license</a></p>'''),
'security':('Security','Document inputs are untrusted.', '''<h2>Report privately</h2><p><a href="https://github.com/gonisulaimann/Prepare/security/advisories/new">Open a private vulnerability report</a>. Include version, platform, reproduction and a minimal synthetic sample. Never put an exploit with sensitive documents in a public issue. No guaranteed response window is promised.</p><h2>Boundaries</h2><p>Inputs, dimensions, byte budgets and page counts are bounded. Conversions are cancellable between codec operations. Platform image/PDF libraries still parse hostile bytes: checks are not a substitute for patched operating systems. Android native stream failures are latched to reject truncated PDFs.</p><h2>PDF parser</h2><p>The PDF beta bundles a local MIT-licensed pdf-lib adapter. Browser jobs use disposable workers with a 30-second deadline; this is not a hard memory cap. File/page limits cannot rule out malicious compressed resources. Use trusted documents. Active or interactive inputs are rejected conservatively; the tool is not a sanitizer.</p><h2>Current limits</h2><p>Mac is ad-hoc signed and not notarized or sandboxed. Android is unsigned experimental. Portable depends on the security of the browser and extensions. No external security audit, malware-proof parser, secure deletion or complete sandbox is claimed.</p>'''),
'faq':('Frequently asked questions','Straight answers about the current product.', '''<h2>Does it upload files?</h2><p>No engine uploads. Use local storage: OS providers, browser extensions and sync clients can have their own network behavior.</p><h2>Can it compress an existing PDF?</h2><p>The image converters make new raster PDFs. The separate PDF beta copies existing pages and enforces a byte ceiling, but does not optimize embedded images or guarantee compression. Mac additionally supports HEIC image input.</p><h2>Why can’t a file fit?</h2><p>The requested byte limit may conflict with page count and the supported quality floor. The application reports failure instead of silently returning an oversized or truncated file.</p><h2>Is grayscale lossless?</h2><p>No. Color conversion and JPEG re-encoding can remove information. Review signatures, stamps and faint marks.</p><h2>Is it open source?</h2><p>Source is publicly inspectable under Hippocratic 3.0 core. Its ethical-use restrictions make ethical-source the accurate description, not OSI-approved open source.</p>'''),
'accessibility':('Accessibility','Keyboard and clear state are product requirements.', '''<h2>Available affordances</h2><p>Semantic web headings and labels, visible focus, keyboard-operable page controls, drag alternatives, live status text and reduced-motion support. Documentation supports browser text zoom and a system light/dark theme.</p><h2>Known limits</h2><p>No WCAG conformance certification is claimed. Generated raster PDFs are not tagged accessible documents and contain no searchable OCR text. Visual source/PDF review cannot replace an accessible text equivalent. Native screen-reader and physical mobile testing remains incomplete.</p><h2>Report a barrier</h2><p>Use the issue tracker with platform, browser or screen reader, the control involved and expected behavior. Do not attach confidential documents.</p><p><a href="/contact/">Report an accessibility issue</a></p>'''),
'about':('About','The space between having a document and having it ready.', '''<p>I’m Goni Sulaiman. I started Prepare to solve file-submission constraints. I am building toward a broader local document-readiness platform: inspect evidence, apply reversible transformations, explain failures and verify the actual output.</p><p>This is independently maintained software, not a claimed corporation or a fabricated team. The preferred next identity Preparo collides with an existing GitHub account and App Store app. Alternative naming and organization ownership are under review; no new namespace is claimed.</p><p><a href="/roadmap/">Direction and release boundaries</a></p>'''),
'community':('Community','Improve the tools without sharing private documents.', '''<h2>Participate</h2><p>Report reproducible bugs, test on hardware we cannot access, improve keyboard flows, translate UI catalogs or contribute synthetic document fixtures. Quality evidence is more valuable than an unsupported platform badge.</p><h2>Conduct</h2><p>I expect respectful, constructive participation. Harassment and disclosure of another person’s private information are not acceptable. The repository Code of Conduct explains how I moderate.</p><p><a href="https://github.com/gonisulaimann/Prepare/blob/main/CODE_OF_CONDUCT.md">Code of Conduct</a> · <a href="/contributing/">Contribute</a></p>'''),
'contributing':('Contributing','Build a tested vertical slice.', '''<p>Clone the repository and read CONTRIBUTING.md and the platform README before editing. Native Mac uses Swift and Apple frameworks. Portable runtime is dependency-free JavaScript; Playwright is test-only. Android uses Java and pinned SDK tools with no runtime libraries.</p><p>Add a failing regression, implement the smallest coherent fix and verify real output. Bound memory, preserve originals, use synthetic fixtures and record platform limitations. Do not add uploads, telemetry, invented success reports or unreviewed cryptography.</p><p>Contributions retain the project’s Hippocratic License 3.0 core. Do not submit code whose license or ownership is incompatible.</p><p><a href="https://github.com/gonisulaimann/Prepare/blob/main/CONTRIBUTING.md">Developer instructions</a></p>'''),
'changelog':('Changelog','Versioned changes, not future claims.', '''<h2>0.7.0-beta.1</h2><p>Real local PDF page operations in a desktop-browser workbench and Node CLI, bounded worker execution, output reparse/geometry checks, richer readiness explanations and updated pinned CI action runtimes. Stable native releases remain unchanged.</p><h2>0.6.0-beta.1</h2><p>Shared readiness engine, reversible Portable history, offline profiles, source CLI and light/dark workbench. Native Mac and Android releases remain at 0.5.0.</p><h2>0.5.0</h2><p>Native DPI ceilings and identity-safe page actions. Portable custom DPI, per-page controls and optional near-white normalization. An independent Android experimental release adds native image preparation with tested exact-byte failure handling.</p><h2>0.4.0</h2><p>Compression profiles, presets, batch controls and a native review workbench.</p><p><a href="https://github.com/gonisulaimann/Prepare/blob/main/CHANGELOG.md">Complete source changelog</a> · <a href="/releases/">Release notes and artifacts</a></p>'''),
'releases':('Releases','Published artifacts with explicit qualification.', '''<h2>PDF workflows beta</h2><p><a href="https://github.com/gonisulaimann/Prepare/releases/tag/v0.7.0-beta.1">0.7.0-beta.1 release and artifacts</a>. Offline PDF Workbench, real PDF source CLI and improved image Portable. Not a new native Mac or Android release.</p><h2>Readiness beta</h2><p><a href="https://github.com/gonisulaimann/Prepare/releases/tag/v0.6.0-beta.1">0.6.0-beta.1 notes and verification</a>. Portable browser workbench and source CLI, not new native binaries.</p><h2>Stable Mac and Portable</h2><p><a href="https://github.com/gonisulaimann/Prepare/releases/tag/v0.5.0">0.5.0 release notes</a>. Mac ZIP and Portable ZIP include SHA-256 companions. Windows/Linux use the same browser archive, not separate native binaries.</p><h2>Experimental Android</h2><p><a href="https://github.com/gonisulaimann/Prepare/releases/tag/v0.5.0-android-experimental.1">Android experimental notes</a>. Unsigned developer artifact, independently reviewed and API28/36 emulator tested.</p><h2>Verification</h2><p>Checksums establish byte integrity, not identity or malware freedom. Mac has an ad-hoc signature, not notarization. Historical release archives remain immutable.</p><p><a href="/download/">Direct downloads and checksums</a></p>'''),
'roadmap':('Roadmap','Capability grows in evidence-backed stages.', '''<h2>Foundation</h2><p>Shared document model, strict profiles, tri-state readiness evidence, immutable transformations, bounded history, offline execution and a CLI independent of UI.</p><h2>Document understanding</h2><p>Sandboxed PDF inspection, local OCR, malformed-input suites and explicit parser provenance. Unknown facts must never become passing checks.</p><h2>Preparation and professional workflows</h2><p>Reusable pipelines, verified exports, batch jobs, comparison and format adapters. Encryption and archival claims require mature libraries and independent validation.</p><h2>Platforms and ecosystem</h2><p>Qualified desktop/mobile hosts, localization, accessible workflows and declarative community profiles. No arbitrary executable plugin loading by default.</p><p>These are directions, not delivery dates or available features. The detailed backlog distinguishes implemented items from proposals.</p><p><a href="/documentation/ROADMAP-100.html">Detailed backlog</a></p>'''),
'licensing':('License','Hippocratic License 3.0 core.', '''<p>The maintainer has explicitly retained Hippocratic License 3.0 core. Source is available for inspection and contributions subject to its terms. The ethical-use restrictions are intentional; this is not an OSI-approved open-source license.</p><p><a href="/LICENSE">Read the complete license</a> · <a href="/NOTICE">Read the notices</a></p><p>The PDF tools bundle pdf-lib under its separate MIT license; attribution and license accompany each download. Original Prepare code remains Hippocratic. <a href="https://github.com/gonisulaimann/Prepare/blob/main/pdf/THIRD-PARTY.md">PDF dependency provenance</a>.</p><p>Historical releases retain their original license and notices. Third-party platform frameworks and developer tooling have separate licenses; inclusion in a build environment does not relicense them.</p>'''),
'contact':('Contact','Use the right channel. Keep private documents private.', '''<h2>Product support and bugs</h2><p><a href="https://github.com/gonisulaimann/Prepare/issues">GitHub issues</a>. State platform, version, expected and actual behavior. Use a synthetic reproduction. No guaranteed turnaround.</p><h2>Security</h2><p><a href="https://github.com/gonisulaimann/Prepare/security/advisories/new">Private vulnerability reporting</a>. Do not publish sensitive attachments.</p><h2>Maintainer</h2><p><a href="https://github.com/gonisulaimann">Goni Sulaiman on GitHub</a>. No support email, office address, phone number or company identity is invented here.</p>''')}
def shell(title,summary,body,path,noindex=False):
    url=BASE+path
    meta_summary=summary+" Local processing with Prepare." if len(summary)<50 else summary
    if path=='download/':
        body='<p id="platform-note" role="status">Choose your platform. All downloads remain available.</p><p><a id="suggested-download" hidden>Suggested desktop download</a></p><p><a href="#readiness-beta">Image readiness beta · or choose PDF Workbench below</a></p>'+body+'<script src="/platform.js" defer></script>'
        body=body.replace('<a href="https://github.com/gonisulaimann/Prepare/releases/download/', '<a class="artifact" href="https://github.com/gonisulaimann/Prepare/releases/download/')
    nav=''.join(f'<a href="/{key}/">{html.escape(value[0])}</a>' for key,value in PAGES.items())
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} — Prepare</title><meta name="description" content="{html.escape(meta_summary)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{html.escape(title)} — Prepare"><meta property="og:description" content="{html.escape(meta_summary)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/social-preview.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{html.escape(title)} — Prepare"><meta name="twitter:description" content="{html.escape(meta_summary)}"><meta name="twitter:image" content="{BASE}assets/social-preview.png"><link rel="icon" href="/assets/icon.svg"><link rel="stylesheet" href="/product.css">{'<meta name="robots" content="noindex">' if noindex else ''}</head><body><a class="skip" href="#content">Skip to content</a><header><a class="wordmark" href="/">Prepare</a><nav aria-label="Primary"><a href="/download/">Download</a><a href="/features/">Features</a><a href="/documentation/">Docs</a></nav></header><main id="content"><p class="kicker">LOCAL DOCUMENT READINESS</p><h1>{html.escape(title)}</h1><p class="lead">{html.escape(summary)}</p>{body}</main><footer><p>Independent software by Goni Sulaiman · Hippocratic 3.0 core</p><nav aria-label="Product and legal">{nav}<a href="/documentation/">Documentation</a></nav></footer></body></html>'''
for key,(title,summary,body) in PAGES.items():
    target=ROOT/key/'index.html';target.parent.mkdir(exist_ok=True);target.write_text(shell(title,summary,body,key+'/'))
(ROOT/'404.html').write_text(shell('Page not found','The address may have changed. Your documents are not involved.','<p><a href="/">Return home</a> or <a href="/documentation/">open documentation</a>.</p>','404.html',True))
print('Generated',len(PAGES),'product pages and real 404')
